// FILE: shipment-detail.component.ts
import {
  Component, ElementRef, Input, OnChanges, OnInit,
  AfterViewInit, OnDestroy, SimpleChanges, ViewChild, signal
} from '@angular/core';

@Component({
  selector: 'app-shipment-detail',
  standalone: true,
  template: `<h2 #heading>Shipment {{ shipmentId }}</h2>
             <p>Refresh attempts: {{ refreshCount() }}</p>`
})
export class ShipmentDetailComponent
  implements OnChanges, OnInit, AfterViewInit, OnDestroy {
  @Input({ required: true }) shipmentId = '';
  @ViewChild('heading') heading?: ElementRef<HTMLHeadingElement>;
  readonly refreshCount = signal(0);
  private timer?: ReturnType<typeof setInterval>;

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['shipmentId']) {
      console.log('Shipment changed:', this.shipmentId);
      // A real feature would update a data stream keyed by ID.
    }
  }
  ngOnInit(): void {
    this.timer = setInterval(() => this.refreshCount.update(n => n + 1), 30_000);
  }
  ngAfterViewInit(): void {
    console.log('Heading element:', this.heading?.nativeElement.tagName);
  }
  ngOnDestroy(): void {
    if (this.timer) clearInterval(this.timer);
  }
}

