import { Component, input, output } from '@angular/core';

export interface Product {
  id: string;
  name: string;
  priceMinor: number;
}

@Component({
  selector: 'app-product-card',
  standalone: true,
  template: `
    <article>
      <h2>{{ product().name }}</h2>
      <p>Price in cents: {{ product().priceMinor }}</p>
      <button type="button" (click)="addToCart.emit(product().id)">
        Add to cart
      </button>
    </article>`
})
export class ProductCardComponent {
  readonly product = input.required<Product>();
  readonly addToCart = output<string>();
}

// FILE: catalog-page.component.ts
import { Component, signal } from '@angular/core';
import { Product, ProductCardComponent } from './product-card.component';

@Component({
  selector: 'app-catalog-page',
  standalone: true,
  imports: [ProductCardComponent],
  template: `
    <app-product-card [product]="product"
      (addToCart)="onAdd($event)" />
    <p>Cart items: {{ cartIds().length }}</p>`
})
export class CatalogPageComponent {
  readonly product: Product = { id: 'SKU-1', name: 'Notebook', priceMinor: 499 };
  readonly cartIds = signal<string[]>([]);
  onAdd(id: string): void {
    this.cartIds.update(ids => [...ids, id]);
  }
}

