      <h3>{{ account().label }}</h3>
      <p>Account: {{ account().maskedNumber }}</p>
      <p>Balance (minor units): {{ account().balanceMinor }}</p>
      <button type="button" (click)="selected.emit(account().id)">
        View details
      </button>
    </article>`
})
export class AccountCardComponent {
  readonly account = input.required<AccountSummary>();
  readonly selected = output<string>();
}

