import { Component, signal } from '@angular/core';
import { AccountCardComponent, AccountSummary } from './account-card.component';

@Component({
  selector: 'app-accounts-dashboard',
  standalone: true,
  imports: [AccountCardComponent],
  template: `
    <h2>My accounts</h2>
    @for (account of accounts; track account.id) {
      <app-account-card
        [account]="account"
        (selected)="selectAccount($event)" />
    }
    <p>Selected account: {{ selectedId() ?? 'none' }}</p>`
})
export class AccountsDashboardComponent {
  readonly accounts: AccountSummary[] = [
    { id: 'a-1', label: 'Savings', maskedNumber: '•••• 1234', balanceMinor: 154250, currency: 'INR' },
    { id: 'a-2', label: 'Current', maskedNumber: '•••• 9876', balanceMinor: 48200, currency: 'INR' }
  ];
  readonly selectedId = signal<string | null>(null);

  selectAccount(id: string): void {
    this.selectedId.set(id);
  }
}
